## 09_fig_NOR_CORE_highlight_8panel_linux.R -----------------------------------
##
## Linux figure: 2 rows x 4 columns
##   a  Cell composition
##   b  CSNK2B
##   c  DDX39B
##   d  RPS5
##   e  LIMA1
##   f  CLIC1
##   g  CTNNB1
##   h  UBE2V1
##
## Input files are generated by 08_prep_cosmx_highlight_8panel_linux.py.
## No cells are subsampled. Each gene panel uses the largest coordinate-
## consistent CosMx archive containing that gene. The dense clouds are
## rasterised before insertion into the PDF, while text remains vector.
##
## Environment variables (optional):
##   COSMX_FIG_WORKDIR   default: ./cosmx_8panel_work
##   COSMX_FIG_OUTDIR    default: <workdir>/figure
##
## Output:
##   Fig_CosMx_highlight_8panel.pdf
##   Fig_CosMx_highlight_8panel.png
##   Fig_CosMx_highlight_8panel_sourcedata.csv
## -----------------------------------------------------------------------------

required_pkgs <- c("data.table", "ggplot2", "patchwork", "scales")
missing_pkgs <- required_pkgs[!vapply(required_pkgs, requireNamespace, logical(1), quietly = TRUE)]
if (length(missing_pkgs)) {
  stop(
    "Missing R packages: ", paste(missing_pkgs, collapse = ", "), "\n",
    "Install them in your Linux R environment, e.g. into R_LIBS_USER, then rerun."
  )
}

suppressPackageStartupMessages({
  library(data.table)
  library(ggplot2)
  library(patchwork)
  library(grid)
})

WORKDIR <- Sys.getenv("COSMX_FIG_WORKDIR", unset = "cosmx_8panel_work")
DIR_FIG <- Sys.getenv("COSMX_FIG_OUTDIR", unset = file.path(WORKDIR, "figure"))
dir.create(DIR_FIG, showWarnings = FALSE, recursive = TRUE)

GENES <- c("CSNK2B", "DDX39B", "RPS5", "LIMA1", "CLIC1", "CTNNB1", "UBE2V1")
DPI <- 300
FIG_W <- 13.6
FIG_H <- 8.2

## Roughly >=300-dpi equivalent within each PDF panel.  Because the point cloud
## is already rasterised, PDF 'dpi' itself does not control these pixels; PX_H
## does. Text and labels remain vector in the PDF.
PX_H <- 1100L

read_any <- function(path) {
  if (!file.exists(path)) stop("Missing input: ", path)
  if (grepl("\\.gz$", path) && !requireNamespace("R.utils", quietly = TRUE)) {
    as.data.table(utils::read.csv(gzfile(path), stringsAsFactors = FALSE))
  } else {
    data.table::fread(path)
  }
}

manifest <- fread(file.path(WORKDIR, "cosmx_panel_manifest.csv"))
comp <- read_any(file.path(WORKDIR, "cosmx_panelA_composition.csv.gz"))

stopifnot(all(GENES %in% manifest$gene))
setkey(manifest, gene)

## ---- rasterisation ----------------------------------------------------------
rasterise_cloud <- function(x, y, value = NULL, ramp = NULL, vmax = NULL,
                            base_col = NULL, px_h = PX_H) {
  ok <- is.finite(x) & is.finite(y)
  if (!is.null(value)) ok <- ok & is.finite(value)
  x <- x[ok]; y <- y[ok]
  if (!is.null(value)) value <- value[ok]
  if (!is.null(base_col) && length(base_col) > 1) base_col <- base_col[ok]

  xr <- range(x); yr <- range(y)
  dx <- diff(xr); dy <- diff(yr)
  if (dx == 0 || dy == 0) stop("Degenerate coordinate range")
  asp <- dx / dy
  ny <- px_h
  nx <- max(1L, as.integer(round(px_h * asp)))

  ix <- pmin(nx, pmax(1L, as.integer(floor((x - xr[1]) / dx * (nx - 1))) + 1L))
  iy <- pmin(ny, pmax(1L, as.integer(floor((y - yr[1]) / dy * (ny - 1))) + 1L))
  cell <- (iy - 1L) * nx + ix

  if (is.null(value)) {
    ## caller sorts the categories so the last point at a pixel wins
    px <- rep(NA_character_, nx * ny)
    px[cell] <- base_col
  } else {
    ## non-expression is visible in pale grey; highest expression at a pixel wins
    mx <- rep(NA_real_, nx * ny)
    o <- order(value)
    mx[cell[o]] <- value[o]
    px <- rep(NA_character_, nx * ny)
    seen <- !is.na(mx)
    px[seen] <- base_col
    hot <- seen & mx > 0
    if (any(hot)) {
      v <- pmin(mx[hot] / vmax, 1)
      px[hot] <- scales::gradient_n_pal(ramp)(v)
    }
  }

  m <- matrix(px, nrow = ny, ncol = nx, byrow = TRUE)
  list(
    raster = m[ny:1L, , drop = FALSE],
    xr = xr,
    yr = yr,
    n_px = sum(!is.na(px)),
    nx = nx,
    ny = ny
  )
}

## ---- palettes ---------------------------------------------------------------
GCOL <- c(
  "Carcinoma"           = "#e34948",
  "Normal epithelium"   = "#1baf7a",
  "Oncofetal"           = "#eda100",
  "Fibroblast / stroma" = "#8a8880",
  "Immune"              = "#9ec5f4",
  "Other"               = "#d8d7d2"
)
G_ORDER <- c(
  "Other", "Immune", "Fibroblast / stroma", "Oncofetal",
  "Normal epithelium", "Carcinoma"
)
EXP_RAMP <- c("#e9e7e1", "#ffd9a0", "#f59b42", "#e34948", "#8f1d2e")
GREY_OFF <- "#eceae5"
INK <- "#0b0b0b"
INK2 <- "#52514e"
INK3 <- "#8a8880"

theme_map <- function() {
  theme_void(base_size = 8) +
    theme(
      plot.title = element_text(
        size = 9.0, face = "bold", colour = INK, hjust = 0,
        margin = margin(b = 1, l = 10)
      ),
      plot.subtitle = element_text(
        size = 5.8, colour = INK2, hjust = 0, lineheight = 1.12,
        margin = margin(b = 2, l = 10)
      ),
      plot.margin = margin(8, 3, 4, 3),
      legend.title = element_text(size = 5.6, colour = INK2),
      legend.text = element_text(size = 5.6, colour = INK2)
    )
}

ghost <- function(xr, yr, n) data.table(x = rep(xr[1], n), y = rep(yr[1], n))

## ---- panel a: cell composition ---------------------------------------------
comp[, group := factor(group, levels = G_ORDER)]
setorder(comp, group)
ra <- rasterise_cloud(
  comp$x, comp$y,
  base_col = GCOL[as.character(comp$group)]
)

gh_a <- ghost(ra$xr, ra$yr, length(G_ORDER))[
  , group := factor(G_ORDER, levels = G_ORDER)
]

pa <- ggplot() +
  annotation_raster(
    ra$raster,
    xmin = ra$xr[1], xmax = ra$xr[2], ymin = ra$yr[1], ymax = ra$yr[2],
    interpolate = FALSE
  ) +
  geom_point(data = gh_a, aes(x, y, colour = group), alpha = 0, size = 0.1) +
  scale_colour_manual(
    values = GCOL,
    breaks = rev(G_ORDER),
    name = NULL,
    guide = guide_legend(override.aes = list(alpha = 1, size = 1.8))
  ) +
  scale_x_continuous(limits = ra$xr, expand = expansion(mult = 0)) +
  scale_y_continuous(limits = ra$yr, expand = expansion(mult = 0)) +
  coord_fixed(clip = "off") +
  labs(
    title = "Cell composition",
    subtitle = sprintf("%s cells", format(nrow(comp), big.mark = ","))
  ) +
  theme_map() +
  theme(
    legend.position = "inside",
    legend.position.inside = c(0.02, 0.27),
    legend.justification = c(0, 0.5),
    legend.key.height = unit(2.7, "mm"),
    legend.key.width = unit(2.7, "mm"),
    legend.background = element_blank()
  )

## ---- gene panels ------------------------------------------------------------
gene_panel <- function(g) {
  f <- file.path(WORKDIR, sprintf("cosmx_expr_%s.csv.gz", g))
  d <- read_any(f)
  info <- manifest[g]
  vmax <- as.numeric(info$expr_vmax)

  rg <- rasterise_cloud(
    d$x, d$y,
    value = d$expr,
    ramp = EXP_RAMP,
    vmax = vmax,
    base_col = GREY_OFF
  )

  gh <- ghost(rg$xr, rg$yr, 2)[, v := c(0, vmax)]
  subtitle <- sprintf(
    "%s cells · %s expressing · q98 %.2f",
    format(nrow(d), big.mark = ","),
    format(sum(d$expressing %in% TRUE), big.mark = ","),
    vmax
  )

  p <- ggplot() +
    annotation_raster(
      rg$raster,
      xmin = rg$xr[1], xmax = rg$xr[2], ymin = rg$yr[1], ymax = rg$yr[2],
      interpolate = FALSE
    ) +
    geom_point(data = gh, aes(x, y, colour = v), alpha = 0, size = 0.1) +
    scale_colour_gradientn(
      colours = EXP_RAMP,
      limits = c(0, vmax),
      oob = scales::squish,
      name = expression(log[2]~"norm. counts"),
      guide = guide_colourbar(
        barwidth = unit(2.0, "mm"),
        barheight = unit(13, "mm"),
        ticks.colour = NA,
        title.position = "left"
      )
    ) +
    scale_x_continuous(limits = rg$xr, expand = expansion(mult = 0)) +
    scale_y_continuous(limits = rg$yr, expand = expansion(mult = 0)) +
    coord_fixed(clip = "off") +
    labs(title = g, subtitle = subtitle) +
    theme_map() +
    theme(
      legend.position = "inside",
      legend.position.inside = c(0.04, 0.23),
      legend.justification = c(0, 0.5),
      legend.title = element_text(size = 5.3, angle = 90, hjust = 0.5),
      plot.title = element_text(
        size = 9.0, face = "bold.italic", colour = INK, hjust = 0,
        margin = margin(b = 1, l = 10)
      )
    )

  rm(d)
  invisible(gc(FALSE))
  p
}

panels <- list(pa)
for (g in GENES) panels[[length(panels) + 1L]] <- gene_panel(g)

## Exact requested order by row:
## row 1: composition, CSNK2B, DDX39B, RPS5
## row 2: LIMA1, CLIC1, CTNNB1, UBE2V1
fig <- wrap_plots(panels, ncol = 4, nrow = 2, byrow = TRUE) +
  plot_annotation(
    tag_levels = "a",
    title = "Spatial expression of highlighted scTWAS CRC genes in CosMx colorectal tissues",
    caption = paste0(
      "No cells were subsampled. For each gene, the largest available coordinate-consistent CosMx archive containing that gene was used; panel a uses the largest archive with cell-type annotations. ",
      "Non-expressing cells are pale grey and expressing cells are coloured by log2-normalised counts, capped at the 98th percentile within each gene. ",
      "The spatial clouds are rasterised at ", PX_H, " pixels in panel height to keep the 300-dpi PDF manageable; labels and text remain vector."
    ),
    theme = theme(
      plot.title = element_text(size = 11, face = "bold", colour = INK, margin = margin(b = 4)),
      plot.caption = element_text(size = 5.5, colour = INK3, hjust = 0, lineheight = 1.2, margin = margin(t = 5)),
      plot.tag = element_text(size = 10, face = "bold", colour = INK),
      plot.margin = margin(5, 5, 5, 5)
    )
  ) &
  theme(plot.tag.position = c(0, 1))

out_pdf <- file.path(DIR_FIG, "Fig_CosMx_highlight_8panel.pdf")
out_png <- file.path(DIR_FIG, "Fig_CosMx_highlight_8panel.png")

## cairo_pdf is preferred on Linux; fall back to the standard pdf device.
pdf_dev <- if (capabilities("cairo")) grDevices::cairo_pdf else grDevices::pdf

ggsave(
  out_pdf, fig,
  width = FIG_W, height = FIG_H, units = "in",
  device = pdf_dev,
  dpi = DPI,
  bg = "white",
  limitsize = FALSE
)

ggsave(
  out_png, fig,
  width = FIG_W, height = FIG_H, units = "in",
  dpi = DPI,
  bg = "white",
  limitsize = FALSE
)

## Source-data / audit trail: exactly which archive and how many cells per panel.
fwrite(
  manifest,
  file.path(DIR_FIG, "Fig_CosMx_highlight_8panel_sourcedata.csv"),
  na = ""
)

cat("Wrote:\n  ", out_pdf, "\n  ", out_png,
    "\nDPI:", DPI, "| raster panel height:", PX_H, "px\n")
